            C++

    #include <iostream>
#include <algorithm>
using namespace std;

string removeSpaces(string& s) {

    // move non-space characters to front
    auto new_end = remove(s.begin(), s.end(), ' ');

    // erase extra part
    s.erase(new_end, s.end());

    return s;
}

